// Backs the loop table: what each form gives you, and what happens to the Vec.
use std::any::type_name_of_val;

#[derive(Clone, Debug, PartialEq)]
struct Person {
    name: String,
    age: u32,
}

fn main() {
    // copies: changing x leaves the Vec alone
    let v = vec![1, 2, 3];
    let mut bumped = Vec::new();
    for mut x in v.iter().copied() {
        x += 1;
        bumped.push(x);
    }
    for mut x in v.clone() {
        x += 1;
        bumped.push(x);
    }
    assert_eq!(bumped, [2, 3, 4, 2, 3, 4]);
    assert_eq!(v, [1, 2, 3]);

    // &v and iter(): shared references, reading only
    let mut sum = 0;
    for x in &v {
        sum += x;
    }
    for x in v.iter() {
        sum += *x;
    }
    assert_eq!(sum, 12);

    // &mut v and iter_mut(): the elements themselves
    let mut w = vec![1, 2, 3];
    for x in &mut w {
        *x += 1;
    }
    for x in w.iter_mut() {
        *x += 10;
    }
    assert_eq!(w, [12, 13, 14]);

    // into_iter on a Vec: the items come out by value, and the Vec is consumed
    let items = vec![String::from("a"), String::from("b")];
    let mut seen = Vec::new();
    for s in items {
        assert_eq!(type_name_of_val(&s), "alloc::string::String");
        seen.push(s);
    }
    assert_eq!(seen.len(), 2);

    // an array of Copy items is itself Copy: the loop uses a copy and the array stays
    let arr = [1, 2, 3];
    let mut from_array = Vec::new();
    for mut x in arr {
        x += 1;
        from_array.push(x);
    }
    assert_eq!(from_array, [2, 3, 4]);
    assert_eq!(arr, [1, 2, 3]);

    // struct elements: x.age through & and &mut
    let mut people = vec![Person {
        name: "Ada".into(),
        age: 36,
    }];
    for p in &people {
        assert_eq!(p.age, 36);
    }
    for p in &mut people {
        p.age += 1;
    }
    assert_eq!(people[0].age, 37);
}

check-mapping.rs.code:
// Backs the "what you write today -> in Rust" tables: every Rust form they show.
use std::collections::HashMap;
use std::ptr;

#[derive(Clone, Debug, PartialEq)]
struct Person {
    name: String,
    age: u32,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct Point {
    x: i32,
    y: i32,
}

struct Counter {
    n: u32,
}

impl Counter {
    fn read(&self) -> u32 {
        self.n
    }
    fn bump(&mut self) {
        self.n += 1;
    }
    fn take(self) -> u32 {
        self.n
    }
}

fn change(p: &mut Person) {
    p.age += 1;
}
fn read(p: &Person) -> u32 {
    p.age
}
fn take(p: Person) -> u32 {
    p.age
}
fn bump_all(people: &mut Vec<Person>) {
    for p in people.iter_mut() {
        p.age += 1;
    }
}
fn push_one(items: &mut Vec<i32>) {
    items.push(1);
}

fn main() {
    let mut people = vec![
        Person {
            name: "Ada".into(),
            age: 36,
        },
        Person {
            name: "Linus".into(),
            age: 54,
        },
    ];

    // Go: for _, p := range people  /  people[i].Age++  /  p := &people[0]
    let mut total = 0;
    for p in &people {
        total += p.age;
    }
    assert_eq!(total, 90);
    for p in &mut people {
        p.age += 1;
    }
    let p = &mut people[0];
    p.age += 1;
    assert_eq!(people[0].age, 38);
    assert_eq!(people[1].age, 55);

    // Go: m[k].Age++ is an error; Rust asks for a mutable lookup
    let mut by_name: HashMap<String, Person> = HashMap::new();
    by_name.insert("ada".into(), people[0].clone());
    if let Some(p) = by_name.get_mut("ada") {
        p.age += 1;
    }
    assert_eq!(by_name["ada"].age, 39);

    // Go: for _, p := range people (a copy of each element)
    let mut copies: Vec<Person> = people.iter().cloned().collect();
    assert_eq!(copies, people);
    bump_all(&mut copies);
    assert_eq!(copies[0].age, people[0].age + 1);

    // struct copy: Copy types copy, others need .clone()
    let a = Point { x: 1, y: 2 };
    let mut b = a;
    b.x = 9;
    assert_eq!((a.x, b.x), (1, 9));
    let c = people[0].clone();
    assert_eq!(c, people[0]);

    // parameters: &mut changes the caller's, & reads, plain takes it
    change(&mut people[1]);
    assert_eq!(read(&people[1]), 56);
    assert_eq!(take(people[1].clone()), 56);

    // slices share, clones do not
    let v = vec![1, 2, 3, 4];
    let part = &v[1..3];
    assert!(ptr::eq(part.as_ptr(), &v[1]));
    let owned = v.clone();
    assert!(!ptr::eq(owned.as_ptr(), v.as_ptr()));
    let mut list = Vec::new();
    push_one(&mut list);
    assert_eq!(list, [1]);

    // methods: self, &self, &mut self
    let mut counter = Counter { n: 0 };
    counter.bump();
    assert_eq!(counter.read(), 1);
    assert_eq!(counter.take(), 1);

    // nested clone is deep for owned data
    let grid = vec![vec![1, 2], vec![3, 4]];
    let mut deep = grid.clone();
    deep[0][0] = 99;
    assert_eq!(grid[0][0], 1);

    // C++: for (auto x : v) / for (const auto& x : v) / for (auto& x : v)
    let names = vec![String::from("a"), String::from("b")];
    let copies: Vec<String> = names.iter().cloned().collect();
    assert_eq!(copies, names);
    let mut nums = vec![1, 2];
    for n in nums.iter().copied() {
        assert!(n > 0);
    }
    for n in &mut nums {
        *n += 1;
    }
    assert_eq!(nums, [2, 3]);

    // identity: ptr::eq on references
    let first = &nums[0];
    let same = &nums[0];
    assert!(ptr::eq(first, same));
    let x = 5;
    let y = 5;
    assert!(!ptr::eq(&x, &y));
}

